"""Convergence-rate lab for first-order methods on diagonal quadratics.

Problem: f(x) = 0.5 * x^T A x, A diagonal positive definite,
         eigenvalues log-spaced in [1/kappa, 1]  (mu = 1/kappa, L = 1).

Methods implemented:
  1. Vanilla gradient descent, textbook optimal fixed step size
         alpha = 2 / (mu + L)                       (= 2*kappa/(kappa+1))
     per-iteration contraction factor on this quadratic: (kappa-1)/(kappa+1).
  2. Polyak heavy-ball momentum, textbook optimal parameters
         alpha = 4 / (sqrt(L) + sqrt(mu))^2
         beta  = ((sqrt(L) - sqrt(mu)) / (sqrt(L) + sqrt(mu)))^2
     per-iteration rate: (sqrt(kappa) - 1) / (sqrt(kappa) + 1).
  3. Nesterov accelerated gradient, standard kappa-based parameters
         alpha = 1 / L
         beta  = (sqrt(kappa) - 1) / (sqrt(kappa) + 1)
     update:  y_t = x_t + beta * (x_t - x_{t-1});  x_{t+1} = y_t - alpha * grad f(y_t)
     per-iteration rate ~ (1 - 1/sqrt(kappa)).
"""

import numpy as np


def make_problem(kappa: int, dim: int = 50):
    """Return A (diagonal matrix as vector of eigenvalues) for f(x)=0.5 x^T A x."""
    eigvals = np.logspace(np.log10(1.0 / kappa), np.log10(1.0), dim)
    return eigvals


def f_val(eigvals, x):
    return 0.5 * float(np.sum(eigvals * x * x))


def grad(eigvals, x):
    return eigvals * x


def _run(update_fn, eigvals, x0, tol=1e-8, max_iter=500_000):
    """Generic loop: update_fn(x, it) returns next iterate."""
    x = x0.copy()
    for it in range(1, max_iter + 1):
        x = update_fn(x, it)
        if f_val(eigvals, x) < tol:
            return it
    raise RuntimeError("did not converge within max_iter")


def gradient_descent(eigvals, x0, tol=1e-8, max_iter=500_000):
    mu, L = eigvals[-1], eigvals[0]
    alpha = 2.0 / (mu + L)

    def step(x, _it):
        return x - alpha * grad(eigvals, x)

    return _run(step, eigvals, x0, tol, max_iter)


def heavy_ball(eigvals, x0, tol=1e-8, max_iter=500_000):
    mu, L = eigvals[-1], eigvals[0]
    sL, smu = np.sqrt(L), np.sqrt(mu)
    alpha = 4.0 / (sL + smu) ** 2
    beta = ((sL - smu) / (sL + smu)) ** 2

    state = {"prev": None}

    def step(x, it):
        if it == 1:
            new = x - alpha * grad(eigvals, x)
        else:
            new = x - alpha * grad(eigvals, x) + beta * (x - state["prev"])
        state["prev"] = x.copy()
        return new

    return _run(step, eigvals, x0, tol, max_iter)


def nesterov(eigvals, x0, tol=1e-8, max_iter=500_000):
    L = eigvals[0]
    kappa = 1.0 / eigvals[-1]
    alpha = 1.0 / L
    beta = (np.sqrt(kappa) - 1.0) / (np.sqrt(kappa) + 1.0)

    state = {"prev": None}

    def step(x, it):
        look = x if state["prev"] is None else x + beta * (x - state["prev"])
        new = x - alpha * grad(eigvals, look)
        state["prev"] = x.copy()
        return new

    return _run(step, eigvals, x0, tol, max_iter)


METHODS = [("GD", gradient_descent), ("HeavyBall", heavy_ball), ("Nesterov", nesterov)]


def run_lab(kappas=(10, 100, 1000)):
    results = {}
    header = f"{'kappa':>6} | {'':>9} | " + " | ".join(f"{name:>9}" for name, _ in METHODS)
    print(header)
    print("-" * len(header))
    for kappa in kappas:
        eigvals = make_problem(kappa)
        x0 = np.ones(len(eigvals))
        row = {}
        for name, method in METHODS:
            row[name] = method(eigvals, x0)
        print(f"{kappa:>6} | {'iters':>9} | " + " | ".join(f"{row[n]:>9d}" for n, _ in METHODS))
        results[kappa] = row
    return results


if __name__ == "__main__":
    run_lab()

